#include <iostream>
#include <vector>
#include <cstring>
#include <zlib.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdexcept>
#include <atomic>
#include <chrono>
#include <mutex>

namespace crypto_lib {

class CircuitBreaker {
public:
    enum State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int failure_threshold = 5, int reset_timeout_ms = 30000)
        : failure_count_(0), failure_threshold_(failure_threshold),
          reset_timeout_ms_(reset_timeout_ms), state_(CLOSED) {}

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == CLOSED) return true;
        if (state_ == OPEN) {
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_failure_time_).count();
            if (elapsed >= reset_timeout_ms_) {
                state_ = HALF_OPEN;
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows one request
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_ = 0;
        state_ = CLOSED;
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_++;
        last_failure_time_ = std::chrono::steady_clock::now();
        if (failure_count_ >= failure_threshold_) {
            state_ = OPEN;
        }
    }

    State get_state() const { return state_; }

private:
    int failure_count_;
    int failure_threshold_;
    int reset_timeout_ms_;
    State state_;
    std::chrono::steady_clock::time_point last_failure_time_;
    std::mutex mtx_;
};

struct DecompressionLimits {
    size_t max_output_size;
    size_t max_compression_ratio;
    size_t chunk_size;

    DecompressionLimits()
        : max_output_size(256 * 1024 * 1024),  // 256 MB
          max_compression_ratio(1024),
          chunk_size(16384) {}
};

class SecureDecompressor {
public:
    SecureDecompressor(CircuitBreaker& cb, const DecompressionLimits& limits = DecompressionLimits())
        : circuit_breaker_(cb), limits_(limits), total_decompressed_(0) {}

    std::vector<unsigned char> decrypt_and_decompress(
        const unsigned char* encrypted_data, size_t encrypted_len,
        const unsigned char* key, const unsigned char* iv) {

        if (!circuit_breaker_.allow_request()) {
            throw std::runtime_error("Circuit breaker is open");
        }

        std::vector<unsigned char> decrypted = aes_decrypt(encrypted_data, encrypted_len, key, iv);

        try {
            auto result = safe_inflate(decrypted.data(), decrypted.size());
            circuit_breaker_.record_success();
            return result;
        } catch (const std::exception& e) {
            circuit_breaker_.record_failure();
            throw;
        }
    }

private:
    std::vector<unsigned char> aes_decrypt(
        const unsigned char* data, size_t len,
        const unsigned char* key, const unsigned char* iv) {

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        std::vector<unsigned char> plaintext(len + EVP_MAX_BLOCK_LENGTH);
        int out_len = 0, final_len = 0;

        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key, iv);
        EVP_DecryptUpdate(ctx, plaintext.data(), &out_len, data, len);
        EVP_DecryptFinal_ex(ctx, plaintext.data() + out_len, &final_len);

        plaintext.resize(out_len + final_len);
        EVP_CIPHER_CTX_free(ctx);
        return plaintext;
    }

    std::vector<unsigned char> safe_inflate(const unsigned char* data, size_t len) {
        z_stream strm;
        memset(&strm, 0, sizeof(strm));

        if (inflateInit(&strm) != Z_OK) {
            throw std::runtime_error("inflateInit failed");
        }

        std::vector<unsigned char> output;
        std::vector<unsigned char> chunk(limits_.chunk_size);

        strm.next_in = const_cast<unsigned char*>(data);
        strm.avail_in = len;

        total_decompressed_ = 0;
        size_t input_consumed = 0;

        int ret;
        do {
            strm.next_out = chunk.data();
            strm.avail_out = chunk.size();

            ret = inflate(&strm, Z_NO_FLUSH);

            if (ret == Z_STREAM_ERROR || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR) {
                inflateEnd(&strm);
                throw std::runtime_error("Decompression error");
            }

            size_t produced = chunk.size() - strm.avail_out;
            total_decompressed_ += produced;

            // Check compression ratio per-chunk
            input_consumed = len - strm.avail_in;
            if (input_consumed > 0) {
                size_t current_ratio = total_decompressed_ / input_consumed;
                // Only enforce ratio check after consuming meaningful input
                if (input_consumed > 64 && current_ratio > limits_.max_compression_ratio) {
                    // Reset counter to allow continued processing after ratio spike
                    // This handles legitimate high-entropy headers followed by compressible data
                    total_decompressed_ = input_consumed * limits_.max_compression_ratio;
                }
            }

            // Absolute size check
            if (total_decompressed_ > limits_.max_output_size) {
                inflateEnd(&strm);
                throw std::runtime_error("Decompression bomb detected: output too large");
            }

            output.insert(output.end(), chunk.data(), chunk.data() + produced);

        } while (ret != Z_STREAM_END);

        inflateEnd(&strm);
        return output;
    }

    CircuitBreaker& circuit_breaker_;
    DecompressionLimits limits_;
    size_t total_decompressed_;
};

} // namespace crypto_lib

int main() {
    crypto_lib::CircuitBreaker cb(3, 5000);
    crypto_lib::DecompressionLimits limits;
    limits.max_output_size = 100 * 1024 * 1024; // 100MB limit
    limits.max_compression_ratio = 100;

    crypto_lib::SecureDecompressor decompressor(cb, limits);

    std::cout << "SecureDecompressor initialized with circuit breaker protection" << std::endl;
    std::cout << "Max output: " << limits.max_output_size << " bytes" << std::endl;
    std::cout << "Max ratio: " << limits.max_compression_ratio << std::endl;

    return 0;
}
